export interface WorkshopProject {
  revision: number;
  stage: "ORACLE" | "ARCHITECT" | "MAKER" | "WITNESS";
  currentSectionId: string | null;
  nextAction: string;
  product: { status: "NONE" | "PROPOSED" | "APPROVED"; proposal: string | null; openQuestions: string[] };
  makerScope: { status: "NONE" | "GRANTED"; statement: string | null };
  sections: Array<{
    id: string;
    title: string;
    order: number;
    content: string;
    version: number;
    hash: string;
    status: "NOT_STARTED" | "DRAFT" | "APPROVED" | "STALE";
  }>;
  transcript: Array<{ id: string; spirit: string; text: string }>;
  operations: Array<{ id: string; kind: string; status: string; result: string | null; nativeSessionId: string | null }>;
  capabilities: Array<{
    id: string;
    purpose: string;
    nativeMapping: string;
    availability: string;
    permission: string;
    observedOutcome: string | null;
  }>;
  witnessDrafts: Array<{ id: string; title: string; content: string }>;
  evidence: Array<{ id: string; checkId: string; result: string; limitation: string | null }>;
}

export interface EngineStatus {
  available: boolean;
  serverVersion: string | null;
  modelAvailable: boolean;
  limitation: string | null;
}

export interface ActionResult {
  project: WorkshopProject;
  duplicate: boolean;
}

export class ApiError extends Error {
  constructor(
    message: string,
    readonly code: string,
    readonly retryable: boolean,
  ) {
    super(message);
  }
}

let sessionToken: string | null = null;

async function token(): Promise<string> {
  if (sessionToken) return sessionToken;
  const response = await fetch("/api/session");
  if (!response.ok) throw new ApiError("The local workshop session could not be opened.", "SESSION", true);
  const body = await response.json() as { token: string };
  sessionToken = REDACTED;
  return sessionToken;
}

async function request<T>(path: string, init?: { method?: string; body?: unknown }): Promise<T> {
  const headers: Record<string, string> = {};
  if (init?.body) {
    headers["content-type"] = "application/json";
    headers["x-ub-session-token"] = await token();
  }
  const response = await fetch(path, {
    method: init?.method ?? "GET",
    headers,
    body: init?.body ? JSON.stringify(init.body) : undefined,
  });
  const body = await response.json() as T & { message?: string; code?: string; retryable?: boolean };
  if (!response.ok) {
    throw new ApiError(body.message ?? "The workshop could not complete that action.", body.code ?? "REQUEST_FAILED", Boolean(body.retryable));
  }
  return body;
}

export function loadProject() {
  return request<WorkshopProject>("/api/project");
}

export function loadEngine() {
  return request<EngineStatus>("/api/engine").catch((error: unknown) => {
    if (error instanceof ApiError) throw error;
    return {
      available: false,
      serverVersion: null,
      modelAvailable: false,
      limitation: "OpenCode could not be reached from this workshop.",
    } satisfies EngineStatus;
  });
}

export function sendMessage(project: WorkshopProject, intent: "clarify" | "draft" | "question" | "witness", text: string) {
  return request<ActionResult>("/api/messages", {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision, intent, text },
  });
}

export function approveProduct(project: WorkshopProject) {
  return request<ActionResult>("/api/approvals", {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision, kind: "product" },
  });
}

export function grantScope(project: WorkshopProject, statement: string) {
  return request<ActionResult>("/api/approvals", {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision, kind: "maker-scope", statement },
  });
}

export function approveSection(project: WorkshopProject, version: number, hash: string, sectionId: string) {
  return request<ActionResult>(`/api/sections/${sectionId}/approve`, {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision, version, hash },
  });
}

export function reviseSection(project: WorkshopProject, sectionId: string, content: string) {
  return request<ActionResult>(`/api/sections/${sectionId}/revisions`, {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision, content },
  });
}

export function runMaker(project: WorkshopProject) {
  return request<ActionResult>("/api/runs", {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision },
  });
}

export function reconcileRun(project: WorkshopProject, operationId: string) {
  return request<ActionResult>(`/api/runs/${operationId}/reconcile`, {
    method: "POST",
    body: { actionId: crypto.randomUUID(), expectedRevision: project.revision },
  });
}

export function loadExport() {
  return request<{ plan: string | null; unresolved: string[]; drafts: Array<{ title: string; content: string }>; limitation: string }>("/api/export");
}

:root {
  color: #f4f0e8;
  background: #111018;
  font-family: ui-sans-serif, system-ui, sans-serif;
  --bg: #111018;
  --surface: #1b1824;
  --raised: #252031;
  --text: #f4f0e8;
  --muted: #b8afca;
  --accent: #f4b66c;
  --spirit: #bfa3ff;
  --success: #8bd5a7;
  --danger: #ffb4a8;
  --space-1: 4px;
  --space-2: 8px;
  --space-3: 12px;
  --space-4: 16px;
  --space-5: 24px;
  --space-6: 32px;
}

body {
  margin: 0;
  min-width: 320px;
  min-height: 100vh;
  background:
    radial-gradient(circle at 20% 0%, rgb(244 182 108 / 16%), transparent 28rem),
    var(--bg);
}

:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 3px;
}

.skip {
  position: absolute;
  left: var(--space-4);
  top: -4rem;
  background: var(--accent);
  color: #111018;
  padding: var(--space-2) var(--space-3);
}

.skip:focus {
  top: var(--space-3);
}

.workshop {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: var(--space-4);
  width: min(1120px, calc(100% - 32px));
  margin: var(--space-5) auto var(--space-6);
}

.stage-strip,
.side,
.document,
.panel {
  background: var(--surface);
  border: 1px solid rgb(244 240 232 / 12%);
  border-radius: 16px;
}

.stage-strip {
  display: flex;
  gap: var(--space-2);
  padding: var(--space-3);
  overflow-x: auto;
}

.stage {
  display: flex;
  align-items: center;
  gap: var(--space-2);
  min-height: 44px;
  border: 0;
  border-radius: 999px;
  padding: var(--space-2) var(--space-3);
  background: transparent;
  color: var(--muted);
  font: inherit;
}

.stage[aria-current="step"] {
  background: var(--raised);
  color: var(--accent);
}

.stage.done {
  color: var(--success);
}

.lantern {
  width: 28px;
  height: 28px;
  flex: none;
}

.document {
  padding: var(--space-5);
  min-width: 0;
}

.eyebrow {
  margin: 0;
  color: var(--spirit);
  font-size: 0.8rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

h1,
h2 {
  font-family: Georgia, "Iowan Old Style", serif;
  font-weight: 500;
}

h1 {
  margin: var(--space-2) 0 var(--space-4);
  color: var(--accent);
  font-size: clamp(2rem, 6vw, 3.5rem);
  line-height: 1.05;
}

h2 {
  margin: 0 0 var(--space-2);
  font-size: 1.4rem;
}

.status-line,
.note,
label,
.side li,
.meta {
  color: var(--muted);
}

label {
  display: grid;
  gap: var(--space-2);
  margin-top: var(--space-4);
}

textarea,
button.action,
.side button {
  font: inherit;
}

textarea {
  width: 100%;
  box-sizing: border-box;
  min-height: 7rem;
  resize: vertical;
  border-radius: 12px;
  border: 1px solid rgb(184 175 202 / 40%);
  background: var(--bg);
  color: var(--text);
  padding: var(--space-3);
  overflow-wrap: anywhere;
}

.actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  margin-top: var(--space-4);
}

.action {
  min-height: 44px;
  border: 0;
  border-radius: 999px;
  padding: var(--space-2) var(--space-4);
  background: var(--accent);
  color: #23180d;
  font-weight: 650;
}

.action.secondary {
  background: var(--raised);
  color: var(--text);
}

.action:disabled {
  opacity: 0.55;
}

.banner {
  margin-top: var(--space-4);
  padding: var(--space-3);
  border-radius: 12px;
  background: var(--raised);
  overflow-wrap: anywhere;
}

.banner.bad {
  color: var(--danger);
}

.banner.good {
  color: var(--success);
}

.prose,
.evidence {
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.reading {
  max-height: 70vh;
  overflow: auto;
  padding-right: var(--space-2);
}

.seal {
  display: inline-block;
  margin-left: var(--space-2);
  color: var(--success);
}

.side {
  display: grid;
  gap: var(--space-4);
  align-content: start;
}

.panel {
  padding: var(--space-4);
  min-width: 0;
}

.panel ol,
.panel ul {
  margin: var(--space-3) 0 0;
  padding-left: 1.1rem;
}

.ghost {
  outline: 1px dashed var(--spirit);
  outline-offset: 2px;
}

.meta {
  font-family: ui-monospace, monospace;
  font-size: 0.85rem;
}

@media (min-width: 960px) {
  .workshop {
    grid-template-columns: minmax(0, 1fr);
  }

  .frame {
    display: grid;
    grid-template-columns: 220px minmax(0, 1fr) 280px;
    gap: var(--space-4);
    align-items: start;
  }
}

@media (prefers-reduced-motion: no-preference) {
  .lantern .flame {
    transform-origin: center;
    animation: flicker 2.8s ease-in-out infinite;
  }
}

@keyframes flicker {
  50% { opacity: 0.72; }
}

@media (prefers-contrast: more) {
  .document,
  .panel,
  .stage-strip,
  textarea {
    border-width: 2px;
    border-color: var(--text);
  }
}

@media (forced-colors: active) {
  .action,
  .stage {
    border: 1px solid ButtonText;
  }

  .lantern {
    forced-color-adjust: auto;
  }
}

import { useEffect, useState } from "react";
import { Eye, Hammer, ScrollText, Sparkles } from "lucide-react";
import { motion, useReducedMotion } from "motion/react";
import {
  ApiError,
  approveProduct,
  approveSection,
  grantScope,
  loadEngine,
  loadExport,
  loadProject,
  reconcileRun,
  reviseSection,
  runMaker,
  sendMessage,
  type EngineStatus,
  type WorkshopProject,
} from "./api.ts";

const spirits = [
  ["ORACLE", "Oracle", Sparkles],
  ["ARCHITECT", "Architect", ScrollText],
  ["MAKER", "Maker", Hammer],
  ["WITNESS", "Witness", Eye],
] as const;

export function App() {
  const [project, setProject] = useState<WorkshopProject | null>(null);
  const [engine, setEngine] = useState<EngineStatus | null>(null);
  const [text, setText] = useState("");
  const [scope, setScope] = useState("Build the approved plan in the isolated demo workspace and leave a passing Node test.");
  const [change, setChange] = useState("");
  const [busy, setBusy] = useState(false);
  const [slow, setSlow] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [exportNote, setExportNote] = useState<string | null>(null);
  const reduceMotion = useReducedMotion();

  useEffect(() => {
    void Promise.all([loadProject(), loadEngine()])
      .then(([loaded, native]) => {
        setProject(loaded);
        setEngine(native);
      })
      .catch((caught: unknown) => {
        setError(caught instanceof Error ? caught.message : "The workshop could not be loaded.");
      });
  }, []);

  async function act(work: () => Promise<{ project: WorkshopProject }>) {
    setBusy(true);
    setSlow(false);
    setError(null);
    const timer = window.setTimeout(() => setSlow(true), 8_000);
    try {
      setProject((await work()).project);
    } catch (caught) {
      const loaded = await loadProject().catch(() => null);
      if (loaded) setProject(loaded);
      setError(caught instanceof ApiError
        ? `${caught.message} ${caught.retryable ? "You can try a new request. The current section was not overwritten." : "Nothing was repeated."}`
        : "The workshop lost its connection. Reload before trying again.");
    } finally {
      window.clearTimeout(timer);
      setBusy(false);
      setSlow(false);
    }
  }

  if (!project) {
    return (
      <main className="workshop">
        <h1>Unfinished Business</h1>
        <p>{error ?? "The workshop is waking up."}</p>
      </main>
    );
  }

  const section = project.sections.find((item) => item.id === project.currentSectionId) ?? null;
  const unknown = project.operations.find((item) => item.status === "UNKNOWN") ?? null;
  const header = section
    ? `${section.title} — section ${section.order} of ${project.sections.length}`
    : project.stage === "ORACLE"
      ? "What's still haunting your to-do list?"
      : project.nextAction;

  return (
    <>
      <a className="skip" href="#document">Skip to the working document</a>
      <main className="workshop">
        <nav className="stage-strip" aria-label="Spirits">
          {spirits.map(([id, label, Icon]) => {
            const done = stageOrder(project.stage) > stageOrder(id);
            return (
              <button key={id} type="button" className={done ? "stage done" : "stage"} aria-current={project.stage === id ? "step" : undefined} disabled>
                <Icon aria-hidden="true" size={18} />
                {label}
              </button>
            );
          })}
        </nav>
        <div className="frame">
          <aside className="side">
            <section className="panel">
              <h2>Outline</h2>
              <ol>
                {project.sections.map((item) => (
                  <li key={item.id} className={item.status === "STALE" ? "ghost" : undefined}>
                    {item.order}. {item.title} — {item.status === "DRAFT" ? `Draft v${item.version}` : item.status}
                  </li>
                ))}
              </ol>
            </section>
          </aside>
          <article className="document" id="document" aria-busy={busy}>
            <Lantern />
            <p className="eyebrow">{project.stage}</p>
            <h1>
              {header}
              {project.product.status === "APPROVED" && section?.status === "APPROVED" ? (
                <Seal label="Approved" reduceMotion={reduceMotion} />
              ) : null}
            </h1>
            <p className="status-line">Stopped here: {project.nextAction}</p>
            {engine && !engine.available ? (
              <p className="banner bad" role="status">{engine.limitation} Start OpenCode on the configured loopback address, then try again. No paid model will be used.</p>
            ) : null}
            {unknown ? (
              <p className="banner bad" role="status">
                A native run is unknown and was not repeated.
                <button className="action secondary" type="button" disabled={busy} onClick={() => void act(() => reconcileRun(project, unknown.id))}>Reconcile native session</button>
              </p>
            ) : null}
            {slow ? <p className="banner" role="status">This is taking longer than usual. The saved section is unchanged until a response arrives.</p> : null}
            {error ? <p className="banner bad" role="alert">{error}</p> : null}

            {project.stage === "ORACLE" ? (
              <OraclePanel project={project} text={text} setText={setText} busy={busy} act={act} />
            ) : null}
            {project.stage === "ARCHITECT" && section ? (
              <ArchitectPanel
                project={project}
                section={section}
                change={change}
                setChange={setChange}
                text={text}
                setText={setText}
                busy={busy}
                act={act}
                reduceMotion={reduceMotion}
              />
            ) : null}
            {project.stage === "ARCHITECT" && !section ? (
              <ScopePanel project={project} scope={scope} setScope={setScope} busy={busy} act={act} />
            ) : null}
            {project.stage === "MAKER" ? (
              <MakerPanel project={project} busy={busy} act={act} />
            ) : null}
            {project.stage === "WITNESS" ? (
              <WitnessPanel project={project} text={text} setText={setText} busy={busy} act={act} exportNote={exportNote} setExportNote={setExportNote} />
            ) : null}
          </article>
          <aside className="side">
            <Activity project={project} />
          </aside>
        </div>
      </main>
    </>
  );
}

function OraclePanel(props: {
  project: WorkshopProject;
  text: string;
  setText: (value: string) => void;
  busy: boolean;
  act: (work: () => Promise<{ project: WorkshopProject }>) => Promise<void>;
}) {
  const proposal = props.project.product.proposal;
  return (
    <>
      <p>Describe an idea you want to bring to life.</p>
      {proposal ? (
        <div className="reading prose">
          <h2>Oracle proposal</h2>
          <p>{proposal}</p>
          {props.project.product.openQuestions.length ? (
            <ul>{props.project.product.openQuestions.map((question) => <li key={question}>{question}</li>)}</ul>
          ) : null}
        </div>
      ) : null}
      <label>
        Idea or question
        <textarea value={props.text} onChange={(event) => props.setText(event.target.value)} maxLength={8000} />
      </label>
      <div className="actions">
        <button className="action" type="button" disabled={props.busy || props.text.trim().length < 1} onClick={() => void props.act(() => sendMessage(props.project, proposal ? "question" : "clarify", props.text))}>
          {proposal ? "Ask a question" : "Wake the Oracle"}
        </button>
        {proposal ? (
          <button className="action secondary" type="button" disabled={props.busy} onClick={() => void props.act(() => approveProduct(props.project))}>
            Approve product
          </button>
        ) : null}
      </div>
    </>
  );
}

function ArchitectPanel(props: {
  project: WorkshopProject;
  section: WorkshopProject["sections"][number];
  change: string;
  setChange: (value: string) => void;
  text: string;
  setText: (value: string) => void;
  busy: boolean;
  reduceMotion: boolean | null;
  act: (work: () => Promise<{ project: WorkshopProject }>) => Promise<void>;
}) {
  return (
    <>
      <p className="meta">{props.section.status} · version {props.section.version}</p>
      {props.section.status === "STALE" ? <p className="banner">An upstream change marked this section stale. Review it again before approval counts.</p> : null}
      <div className="reading prose">
        {props.section.content || "This section has no draft yet."}
      </div>
      {props.section.status === "APPROVED" ? <Seal label="Section approved" reduceMotion={props.reduceMotion} /> : null}
      <div className="actions">
        <button className="action" type="button" disabled={props.busy} onClick={() => void props.act(() => sendMessage(props.project, "draft", props.text.trim() || `Draft ${props.section.title}`))}>
          Draft section
        </button>
        {props.section.status === "DRAFT" ? (
          <button className="action secondary" type="button" disabled={props.busy} onClick={() => void props.act(() => approveSection(props.project, props.section.version, props.section.hash, props.section.id))}>
            Approve section
          </button>
        ) : null}
      </div>
      <label>
        Ask a question
        <textarea value={props.text} onChange={(event) => props.setText(event.target.value)} maxLength={8000} />
      </label>
      <button className="action secondary" type="button" disabled={props.busy || props.text.trim().length < 1} onClick={() => void props.act(() => sendMessage(props.project, "question", props.text))}>
        Ask
      </button>
      <label>
        Request changes to this section
        <textarea value={props.change} onChange={(event) => props.setChange(event.target.value)} maxLength={8000} />
      </label>
      <button className="action secondary" type="button" disabled={props.busy || props.change.trim().length < 1} onClick={() => void props.act(() => reviseSection(props.project, props.section.id, props.change))}>
        Request changes
      </button>
    </>
  );
}

function ScopePanel(props: {
  project: WorkshopProject;
  scope: string;
  setScope: (value: string) => void;
  busy: boolean;
  act: (work: () => Promise<{ project: WorkshopProject }>) => Promise<void>;
}) {
  return (
    <>
      <p>Every current section is approved. Maker still needs a separate scope before any native edit.</p>
      <label>
        Maker scope
        <textarea value={props.scope} onChange={(event) => props.setScope(event.target.value)} maxLength={2000} />
      </label>
      <button className="action" type="button" disabled={props.busy || props.scope.trim().length < 8} onClick={() => void props.act(() => grantScope(props.project, props.scope.trim()))}>
        Grant Maker scope
      </button>
    </>
  );
}

function MakerPanel(props: {
  project: WorkshopProject;
  busy: boolean;
  act: (work: () => Promise<{ project: WorkshopProject }>) => Promise<void>;
}) {
  const recommended = props.project.capabilities.find((item) => item.id === "node-check");
  return (
    <>
      <p>Scope: {props.project.makerScope.statement}</p>
      {recommended ? (
        <p className="banner">Recommended path: {recommended.purpose}. {recommended.nativeMapping}. Permission: {recommended.permission}.</p>
      ) : null}
      <button className="action" type="button" disabled={props.busy} onClick={() => void props.act(() => runMaker(props.project))}>
        Run Maker
      </button>
    </>
  );
}

function WitnessPanel(props: {
  project: WorkshopProject;
  text: string;
  setText: (value: string) => void;
  busy: boolean;
  act: (work: () => Promise<{ project: WorkshopProject }>) => Promise<void>;
  exportNote: string | null;
  setExportNote: (value: string | null) => void;
}) {
  return (
    <>
      <p>Witness reads the evidence in a fresh session and writes review notes. Those notes are not a submitted article or video.</p>
      <label>
        What should Witness examine?
        <textarea value={props.text} onChange={(event) => props.setText(event.target.value)} maxLength={8000} />
      </label>
      <div className="actions">
        <button className="action" type="button" disabled={props.busy || props.text.trim().length < 1} onClick={() => void props.act(() => sendMessage(props.project, "witness", props.text))}>
          Review evidence
        </button>
        <button className="action secondary" type="button" disabled={props.busy} onClick={() => void loadExport().then((exported) => props.setExportNote(exported.limitation + (exported.plan ? " Compiled plan is ready." : " Plan is not fully approved."))).catch((caught: unknown) => props.setExportNote(caught instanceof Error ? caught.message : "Export failed."))}>
          Check export
        </button>
      </div>
      {props.exportNote ? <p className="banner" role="status">{props.exportNote}</p> : null}
      {props.project.witnessDrafts.map((draft) => (
        <section key={draft.id} className="reading">
          <h2>{draft.title}</h2>
          <p className="prose">{draft.content}</p>
        </section>
      ))}
    </>
  );
}

function Activity({ project }: { project: WorkshopProject }) {
  const latest = [...project.operations].reverse().slice(0, 4);
  return (
    <>
      <section className="panel">
        <h2>Activity</h2>
        {latest.length === 0 ? <p>No native run yet.</p> : (
          <ul>
            {latest.map((item) => (
              <li key={item.id}>
                <span className="meta">{item.kind} · {item.status}</span>
                <div className="evidence">{item.result ?? "No result recorded."}</div>
              </li>
            ))}
          </ul>
        )}
      </section>
      <section className="panel">
        <h2>Evidence</h2>
        {project.evidence.length === 0 ? <p>No check has been observed.</p> : (
          <ul>
            {project.evidence.map((item) => (
              <li key={item.id}>{item.checkId}: {item.result}{item.limitation ? ` — ${item.limitation}` : ""}</li>
            ))}
          </ul>
        )}
      </section>
    </>
  );
}

function Seal({ label, reduceMotion }: { label: string; reduceMotion: boolean | null }) {
  if (reduceMotion) return <span className="seal">{label}</span>;
  return <motion.span className="seal" initial={{ opacity: 0 }} animate={{ opacity: 1 }} transition={{ duration: 0.35 }}>{label}</motion.span>;
}

function Lantern() {
  return (
    <svg className="lantern" viewBox="0 0 32 32" aria-hidden="true">
      <rect x="12" y="3" width="8" height="3" rx="1" fill="#f4b66c" />
      <path d="M10 8h12l-1 16H11L10 8z" fill="#252031" stroke="#f4b66c" />
      <circle className="flame" cx="16" cy="16" r="3" fill="#f4b66c" />
    </svg>
  );
}

function stageOrder(stage: WorkshopProject["stage"]): number {
  return spirits.findIndex(([id]) => id === stage);
}

