import { spawn } from "node:child_process";
import { writeFile } from "node:fs/promises";

const chrome = spawn("/usr/bin/google-chrome", [
  "--headless=new", "--disable-gpu", "--no-sandbox",
  "--remote-debugging-port=9335",
  "--user-data-dir=/tmp/ub-chrome-profile-3",
  "about:blank",
], { stdio: "ignore" });
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
for (let attempt = 0; attempt < 50; attempt += 1) {
  try { if ((await fetch("http://127.0.0.1:9335/json/version")).ok) break; } catch { /* starting */ }
  await sleep(200);
}
const target = await (await fetch("http://127.0.0.1:9335/json/new?about:blank", { method: "PUT" })).json();
const socket = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => {
  socket.addEventListener("open", resolve);
  socket.addEventListener("error", reject);
});
let nextId = 0;
const pending = new Map();
socket.addEventListener("message", (event) => {
  const message = JSON.parse(event.data);
  if (message.id && pending.has(message.id)) {
    pending.get(message.id)(message);
    pending.delete(message.id);
  }
});
const send = (method, params = {}) => new Promise((resolve) => {
  const id = ++nextId;
  pending.set(id, resolve);
  socket.send(JSON.stringify({ id, method, params }));
});
async function evaluate(expression) {
  const response = await send("Runtime.evaluate", { expression, returnByValue: true, awaitPromise: true });
  if (response.result.exceptionDetails) throw new Error(JSON.stringify(response.result.exceptionDetails));
  return response.result.result.value;
}
async function shot(name) {
  const response = await send("Page.captureScreenshot", { format: "png" });
  await writeFile(`/tmp/${name}.png`, Buffer.from(response.result.data, "base64"));
}
await send("Page.enable");
await send("Emulation.setDeviceMetricsOverride", { width: 1280, height: 900, deviceScaleFactor: 1, mobile: false });
await send("Page.navigate", { url: "http://127.0.0.1:4317/" });
await sleep(800);
const desktop = await evaluate(`(() => {
  const field = document.querySelector("textarea");
  field?.focus({ focusVisible: true });
  const focused = field ? getComputedStyle(field) : null;
  const text = getComputedStyle(document.body);
  const muted = getComputedStyle(document.querySelector(".status-line") ?? document.body);
  return {
    title: document.querySelector("h1")?.textContent,
    stage: document.querySelector(".eyebrow")?.textContent,
    drafts: document.body.innerText.includes("Findings"),
    failure: document.body.innerText.includes("SyntaxError") || document.body.innerText.includes("CK-06"),
    outline: focused?.outlineStyle,
    outlineWidth: focused?.outlineWidth,
    bodyColor: text.color,
    bodyBg: text.backgroundColor,
    muted: muted.color,
  };
})()`);
console.log("WITNESS", JSON.stringify(desktop));
await shot("ub-witness-desktop");
await send("Emulation.setDeviceMetricsOverride", { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });
await sleep(300);
await send("Page.navigate", { url: "http://127.0.0.1:4318/" });
await sleep(800);
const typed = await evaluate(`(() => {
  const field = document.querySelector("textarea");
  const setter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, "value").set;
  setter.call(field, "A short idea");
  field.dispatchEvent(new Event("input", { bubbles: true }));
  return document.querySelector("h1")?.textContent;
})()`);
await sleep(200);
await evaluate(`(() => [...document.querySelectorAll("button")].find((item) => item.textContent.includes("Wake the Oracle"))?.click())()`);
let alertText = "";
for (let attempt = 0; attempt < 15; attempt += 1) {
  await sleep(500);
  alertText = await evaluate(`(() => document.querySelector("[role=alert]")?.innerText ?? "")()`);
  if (alertText) break;
}
console.log("ERROR_PAGE", typed, alertText.slice(0, 300));
await shot("ub-error-narrow");
chrome.kill();
socket.close();

